// v2.13 算法移植，坐标使用运行时的 32px 逻辑轨道。
const motionPreference = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;
const ventRatios = [0.35, 0.72, 0.95];

return {
  init({ h }) {
    const rand = h.rand(21300);
    const particles = Array.from({ length: 36 }, () => ({
      relDist: rand(),
      x: rand() * 360,
      y: rand() * 32,
      vx: 0.6 + rand() * 2.4,
      vy: (rand() - 0.5) * 1.2,
      size: 1.2 + rand() * 3.6
    }));
    return { lastTime: null, flashTime: 0, wasMax: false, afterglow: 0, particles, rand, particleWidth: 360 };
  },
  draw(ctx, s) {
    const { width, height, pal, dark, state } = s;
    const thumbX = Math.max(0, Math.min(s.end, width));
    if (thumbX <= 0) return;
    const L2 = s.high;
    const L3 = s.max;
    const reduced = Boolean(motionPreference?.matches);
    const time = reduced ? 0 : s.time;
    const burstT = reduced ? 0 : s.burst;
    const isBursting = burstT > 0;
    const isMaxEffort = L3 >= 0.94;
    const cruisePulse = isMaxEffort ? 0.5 + 0.5 * Math.sin(time * 1.8) : 0;

    // 用运行时已调整流速的时间推进粒子，流速归零时定格。
    const elapsed = state.lastTime === null || reduced ? 0 : Math.max(0, time - state.lastTime);
    // 连续高亮脉冲保持在每秒三次以下。
    state.flashTime = state.lastTime === null ? time : state.flashTime + Math.min(elapsed, s.dt * 0.033);
    const flashTime = reduced ? 0 : state.flashTime;
    state.lastTime = time;
    const frameStep = Math.min(s.dt * 4, elapsed / 0.035);
    const currentRatio = s.ratio ?? thumbX / Math.max(1, width);
    const overdrive = isMaxEffort ? 1 : Math.max(0, (currentRatio - 0.65) / 0.35);
    let targetBudget = 0;
    if (currentRatio >= 0.95) targetBudget = Math.round(60 + ((currentRatio - 0.95) / 0.05) * 68);
    else if (currentRatio >= 0.4) targetBudget = Math.round(18 + ((currentRatio - 0.4) / 0.55) * 34);
    else if (currentRatio >= 0.02) targetBudget = Math.round(6 + (currentRatio / 0.4) * 8);
    targetBudget = Math.min(state.particles.length, isBursting ? 128 : targetBudget);
    const { particles } = state;
    const secondary = s.monet?.enabled ? s.monet.secondary : pal;

    ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
    state.afterglow = state.wasMax && !isMaxEffort ? 1 : Math.max(0, state.afterglow - s.dt / 24);
    state.wasMax = isMaxEffort;
    const afterglowT = reduced ? 0 : state.afterglow;

    // 1. 高温炽热熔岩渐变底色（绝无任何死黑底色！完全联动主题色）
    const magmaGrad = ctx.createLinearGradient(0, 0, thumbX, 0);
    magmaGrad.addColorStop(0, pal.deep(0.7));      // 高温凝态岩层底
    magmaGrad.addColorStop(0.45, secondary.main(0.85));  // 炽热岩浆主流色
    magmaGrad.addColorStop(1, pal.light(0.95));    // 喷发源白炽高光
    ctx.fillStyle = magmaGrad;
    ctx.fillRect(0, 0, thumbX, height);

    // 2. 粘稠熔岩内部流线
    ctx.save();
    ctx.strokeStyle = pal.light(0.35);
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    for (let x = 0; x <= thumbX; x += 8) {
      const cy = height * 0.45 + Math.sin(x * 0.06 - time * 2.5) * (height * 0.18);
      if (x === 0) ctx.moveTo(x, cy);
      else ctx.lineTo(x, cy);
    }
    ctx.stroke();

    // 3. 熔岩表面起伏波浪 (Molten Lava Surface Crests)
    ctx.fillStyle = pal.light(0.45);
    ctx.beginPath();
    ctx.moveTo(0, height);
    for (let x = 0; x <= thumbX; x += 6) {
      const wy = height * 0.52 + Math.sin(x * 0.08 + time * 3.5) * (height * 0.2) + Math.cos(x * 0.15 - time * 2) * (height * 0.08);
      ctx.lineTo(x, wy);
    }
    ctx.lineTo(thumbX, height);
    ctx.closePath();
    ctx.fill();

    // 4. 火山岩浆气泡鼓起与爆裂 (Boiling Magma Bubbles)
    const bubbleCount = 4;
    for (let b = 0; b < bubbleCount; b++) {
      const bPhase = (time * (2 + b * 0.6) + b * 1.5) % 3;
      const bx = thumbX * (0.2 + b * 0.22) + Math.sin(time + b) * 8;
      if (bx > 5 && bx < thumbX - 5) {
        const by = height * 0.5 + Math.sin(bx * 0.08 + time * 3.5) * (height * 0.18);
        if (bPhase < 2.3) {
          const bRadius = (1 + (bPhase / 2.3) * 3.5);
          ctx.beginPath();
          ctx.arc(bx, by - bRadius * 0.5, bRadius, 0, Math.PI * 2);
          ctx.fillStyle = pal.light(0.85);
          ctx.fill();
          ctx.strokeStyle = "#ffffff";
          ctx.lineWidth = 0.8;
          ctx.stroke();
        } else {
          const splashP = (bPhase - 2.3) / 0.7;
          const splashR = splashP * 6;
          ctx.fillStyle = "#ffffff";
          ctx.fillRect(bx - splashR, by - splashR * 0.8, 1.2, 1.2);
          ctx.fillRect(bx + splashR, by - splashR * 0.8, 1.2, 1.2);
        }
      }
    }

    // 5. 火山口向上剧烈喷涌的液态熔岩柱 (Lava Fountain)
    for (let v = 0; v < ventRatios.length; v++) {
      const vx = thumbX * ventRatios[v];
      if (vx > 10 && vx <= thumbX) {
        const eruptH = (14 + Math.sin(flashTime * 9 + v * 2.8) * 7 + overdrive * 9);
        ctx.beginPath();
        ctx.moveTo(vx - 6, height);
        ctx.quadraticCurveTo(vx - 2, height / 2 - eruptH * 0.5, vx, height / 2 - eruptH);
        ctx.quadraticCurveTo(vx + 2, height / 2 - eruptH * 0.5, vx + 6, height);
        ctx.closePath();
        ctx.fillStyle = pal.light(0.9);
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(vx - 2.5, height);
        ctx.lineTo(vx, height / 2 - eruptH * 0.85);
        ctx.lineTo(vx + 2.5, height);
        ctx.closePath();
        ctx.fillStyle = "#ffffff";
        ctx.fill();
      }
    }

    // 进度变化时一起缩放粒子的横坐标，保证窄轨道也能看见岩浆块。
    if (state.particleWidth !== thumbX) {
      const change = thumbX / state.particleWidth;
      for (const particle of particles) particle.x *= change;
      state.particleWidth = thumbX;
    }

    // 6. 重力抛物线岩浆块与流火余烬
    for (let i = 0; i < Math.min(36, targetBudget); i++) {
      const p = particles[i];
      p.vy += (0.14 + overdrive * 0.08) * frameStep;
      p.y += p.vy * frameStep;
      p.x -= (0.5 + p.vx * 0.4) * frameStep;
      if (p.y > height + 4 || p.y < -8 || p.x < 0) {
        const chosenVent = ventRatios[i % ventRatios.length];
        p.x = thumbX * chosenVent + (state.rand() - 0.5) * 10;
        p.y = height * 0.45;
        p.vy = -(2.0 + state.rand() * 2.5 + overdrive * 1.5);
      }
      const dropSz = p.size * (1 + overdrive * 0.35);
      ctx.fillStyle = i % 3 === 0 ? "#ffffff" : (i % 2 === 0 ? pal.light(0.95) : pal.main(0.9));
      ctx.fillRect(p.x, p.y, dropSz, dropSz);
    }
    ctx.restore();
    // High：熔岩泡鼓起与破裂
    if (L2 > 0.01) {
      for (let b2 = 0; b2 < 8; b2++) {
        const ph2 = (time * (1.6 + b2 * 0.2) + b2 * 1.3) % 3;
        if (ph2 > 2.2) continue;
        const bx2 = thumbX * (0.1 + b2 * 0.1) + Math.sin(time + b2) * 6;
        if (bx2 > thumbX - 4) continue;
        const by2 = height * 0.62 + Math.sin(bx2 * 0.08 + time * 3) * height * 0.1;
        const br2 = (1 + ph2 * 1.6) * L2;
        ctx.beginPath();
        ctx.arc(bx2, by2 - br2 * 0.4, br2, 0, Math.PI * 2);
        ctx.fillStyle = pal.light(0.8 * L2);
        ctx.fill();
      }
    }
    // Max：爆发柱 + 火星雨
    if (L3 > 0.01) {
      for (let m2 = 0; m2 < 22; m2++) {
        const p = particles[m2];
        p.y -= (0.12 + p.size * 0.05) * frameStep * (1 + overdrive);
        if (p.y < 0) {
          p.y = 32;
          p.relDist = (p.relDist * 7.7) % 1;
        }
        const mx2 = ((p.relDist * 1.3) % 1) * thumbX;
        const my2 = (p.y / 32) * height;
        ctx.fillStyle = m2 % 3 === 0 ? "rgba(255, 255, 255, 0.9)" : pal.light(0.72 * L3);
        ctx.fillRect(mx2, my2, 1.4, 1.4);
      }
      const col4 = ctx.createLinearGradient(0, height, 0, 0);
      col4.addColorStop(0, pal.light(0.42 * L3));
      col4.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = col4;
      ctx.fillRect(thumbX - 28, 0, 28, height);
    }

    // 【L2 结构层】克制的顶边高光与丝滑掠过扫光，让 High 更有层次又不遮挡主体动效
    if (L2 > 0.01) {
      const topSheen = ctx.createLinearGradient(0, 0, thumbX, 0);
      topSheen.addColorStop(0, "rgba(255, 255, 255, 0)");
      topSheen.addColorStop(0.5, `rgba(255, 255, 255, ${(0.18 * L2).toFixed(3)})`);
      topSheen.addColorStop(1, `rgba(255, 255, 255, ${(0.36 * L2).toFixed(3)})`);
      ctx.fillStyle = topSheen;
      ctx.fillRect(0, 1.0, thumbX, 1.2);

      const sweepX = ((time * 0.36) % 1) * (thumbX + 150) - 75;
      const sweepGrad = ctx.createLinearGradient(sweepX - 50, 0, sweepX + 50, 0);
      sweepGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      sweepGrad.addColorStop(0.5, `rgba(255, 255, 255, ${(0.18 * L2).toFixed(3)})`);
      sweepGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = sweepGrad;
      const left = Math.max(0, sweepX - 50);
      const right = Math.min(thumbX, sweepX + 50);
      if (right > left) ctx.fillRect(left, 0, right - left, height);
    }

    // 【L3 高能层】美学克制版 Max 光冠：径向柔核 + 6 道细光晕 + 2 圈柔波，告别杂乱激光与方块噪点
    if (L3 > 0.01) {
      const crownR = Math.max(height * 1.45, 38);
      const crown = ctx.createRadialGradient(thumbX, height * 0.5, 0, thumbX, height * 0.5, crownR);
      crown.addColorStop(0, `rgba(255, 255, 255, ${(0.42 * L3 * (0.88 + 0.12 * cruisePulse)).toFixed(3)})`);
      crown.addColorStop(0.45, pal.light(0.24 * L3));
      crown.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = crown;
      ctx.beginPath();
      ctx.arc(thumbX, height * 0.5, crownR, 0, Math.PI * 2);
      ctx.fill();

      const rayR = Math.max(height * 0.95, 28);
      for (let r = 0; r < 6; r++) {
        const ra = time * 1.15 + (r / 6) * Math.PI * 2;
        const rl = rayR * (0.55 + 0.45 * Math.sin(time * 2.1 + r * 1.4));
        const rayGrad = ctx.createLinearGradient(thumbX, height * 0.5,
          thumbX + Math.cos(ra) * rl, height * 0.5 + Math.sin(ra) * rl);
        rayGrad.addColorStop(0, `rgba(255, 255, 255, ${(0.34 * L3).toFixed(3)})`);
        rayGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
        ctx.strokeStyle = rayGrad;
        ctx.lineWidth = 1.1;
        ctx.beginPath();
        ctx.moveTo(thumbX, height * 0.5);
        ctx.lineTo(thumbX + Math.cos(ra) * rl, height * 0.5 + Math.sin(ra) * rl);
        ctx.stroke();
      }

      for (let k = 0; k < 2; k++) {
        const ph = (time * 0.68 + k * 0.5) % 1;
        const rr = ph * width * 0.42;
        const aa = (1 - ph) * 0.30 * L3;
        if (aa < 0.02) continue;
        ctx.strokeStyle = `rgba(255, 255, 255, ${aa.toFixed(3)})`;
        ctx.lineWidth = 1.5 * (1 - ph) + 0.5;
        ctx.beginPath();
        ctx.arc(thumbX, height * 0.5, rr, Math.PI * 0.5, Math.PI * 1.5);
        ctx.stroke();
      }

      const rimGrad = ctx.createLinearGradient(0, 0, thumbX, 0);
      rimGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      rimGrad.addColorStop(Math.min(1, Math.max(0, 0.55 + 0.3 * Math.sin(time * 0.8))), `rgba(255, 255, 255, ${(0.32 * L3).toFixed(3)})`);
      rimGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = rimGrad;
      ctx.fillRect(0, 0.6, thumbX, 1.2);
      ctx.fillRect(0, height - 1.8, thumbX, 1.2);
    }

    if (isBursting) {
      const shockRadius = (1 - burstT) * width * 0.85;
      ctx.save();
      ctx.strokeStyle = dark ? `rgba(255, 255, 255, ${burstT * 0.85})` : pal.main(burstT * 0.75);
      ctx.lineWidth = 3.5 * burstT;
      ctx.beginPath();
      ctx.arc(thumbX, height / 2, shockRadius, 0, Math.PI * 2);
      ctx.stroke();

      // 全轨高光冲洗 (Flash Wash)
      ctx.fillStyle = dark ? `rgba(255, 255, 255, ${burstT * 0.35})` : `rgba(255, 255, 255, ${burstT * 0.2})`;
      ctx.fillRect(0, 0, thumbX, height);
      ctx.restore();
    }

    // ---------------------------------------------------------
    // ③ 降档余韵尾迹 (Afterglow: 0.4s)
    // ---------------------------------------------------------
    if (afterglowT > 0) {
      ctx.save();
      ctx.fillStyle = pal.light(afterglowT * 0.25);
      ctx.fillRect(0, 0, thumbX, height);
      ctx.restore();
    }
  }
};
